contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint amount) public payable {
        uint before = c.proposalCount();
        c.newGrantProposal(recipient, amount);
        uint afterCount = c.proposalCount();
        string memory newType = c.mapPID_type(afterCount);
        require(before < afterCount);
        if (before > 0) {
            string memory oldType = c.mapPID_type(before);
            assert(isEqual(newType, "GRANT") && isEqual(oldType, c.mapPID_type(before)));
        } else {
            assert(isEqual(newType, "GRANT"));
        }
    }

    function isEqual(string memory a, string memory b) internal pure returns (bool) {
        return keccak256(bytes(a)) == keccak256(bytes(b));
    }

    receive() external payable {}
}

