contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint oldProposalID, uint newProposalID) public payable {
        // Read the pre-call vote count for the new proposal ID.
        // The transaction reverts if the new proposal ID is out of range,
        // so this read must happen after setup but before the deciding call.
        uint newVotesBefore = c.mapPID_votes(newProposalID);

        bool reverted;
        try c.cancelProposal(oldProposalID, newProposalID) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(
                c.mapPID_votes(oldProposalID) == 0 &&
                c.mapPID_votes(newProposalID) == newVotesBefore
            );
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint oldProposalID, uint newProposalID) public payable {
        uint newVotesBefore = c.mapPID_votes(newProposalID);

        bool reverted;
        try c.cancelProposal(oldProposalID, newProposalID) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint oldVotesAfter = c.mapPID_votes(oldProposalID);
        uint newVotesAfter = c.mapPID_votes(newProposalID);

        assert(reverted || (oldVotesAfter == 0 && newVotesAfter == newVotesBefore));
    }

    receive() external payable {}
}
